// Base de datos de juegos - Menudos Artistas (Teatro Ugena infantil)
// Separada de data/juegos.js (ImproXpresión) el 15/09/2026.
// Incluye: guiones de clase de Menudos Artistas (curso 2024-2025 y 2025-2026) y dinámicas de Jornadas La Consti.
// Campos: id, t=titulo, c=categorias[], e=edad (ninos|adultos|ambos), a=autor/fuente persona, src=documento origen, d=descripcion, v=variantes
const JUEGOS_MENUDOS = [
{id:"balas-energia",t:"Balas de energía",c:["Calentamiento","Energía"],e:"ambos",a:"Edu",src:"Dinámicas La Consti",d:"En círculo. Una persona crea un gesto con un sonido y lo pasa. Quien lo recibe repite el gesto y sonido lo más parecido posible e inventa uno nuevo que pasa al siguiente.",v:"Con saltitos, con miradas, con chasquidos; varias balas simultáneas; con el nombre de cada uno."},
{id:"calentamiento-7",t:"Calentamiento del 7",c:["Calentamiento","Ritmo"],e:"ambos",a:"Edu",src:"guion_9_navidad",d:"Del 1 al 7 pasamos la energía con la mano en el hombro; el 7 hace 'esa cosa rara' y se reinicia."},
{id:"tra-tre-tri",t:"TRA TRE TRI TRO TRU",c:["Calentamiento","Energía","Voz"],e:"ambos",a:"Edu",src:"guion_0710",d:"En círculo se pasa la energía con sílabas: TRA a la derecha, TRE a la izquierda, TRI a cualquiera señalando, TRO intercambio de sitio con el receptor, TRU todos bailan y cambian de lugar."},
{id:"moleculas",t:"Moléculas / Juego del átomo",c:["Calentamiento","Energía","Espacio"],e:"ambos",a:"Edu",src:"Dinámicas La Consti / guion_17",d:"Caminamos rellenando huecos. Cada uno elige en secreto a alguien que le 'atrae': a la palmada, hombro con hombro con esa persona. Luego se añade alguien que 'repele' y se combinan ambos a la vez.",v:"Versión átomo: protones y electrones, cargas iguales se repelen y distintas se atraen."},
{id:"que-rodilla",t:"Qué rodilla",c:["Calentamiento","Desinhibición"],e:"niños",a:"Edu",src:"Dinámicas La Consti",d:"Cada uno se tapa una rodilla con una mano y con la otra intenta tocar la rodilla de los demás. Mucho movimiento: vigilar que no se descontrole.",v:"Con el hombro; con la mano en la espalda."},
{id:"no-me-mires",t:"No me mires (espacio reducido)",c:["Calentamiento","Desinhibición","Espacio"],e:"ambos",a:"Edu",src:"Dinámicas La Consti / guion_0710",d:"Andar por el espacio sin tocarse ni mirarse a los ojos mientras el facilitador reduce el espacio (con bancos o líneas) hasta dejarlo mínimo."},
{id:"contar-10-grupo",t:"Contar hasta 10 sin pisarse",c:["Escucha","Concentración"],e:"ambos",a:"Edu",src:"guion_28",d:"El grupo cuenta del 1 al 10 (y vuelta) sin orden pactado: si dos hablan a la vez, se empieza de nuevo. Sin trucos."},
{id:"movimiento-limitado",t:"Movimiento limitado",c:["Calentamiento","Cuerpo"],e:"ambos",a:"Edu",src:"Dinámicas La Consti",d:"Con música rítmica nos movemos libres; progresivamente se prohíbe mover pies, piernas, cintura, tronco, manos, brazos, hombros, cuello, cabeza... hasta solo ojos y cejas."},
{id:"stop-cooperativo",t:"El Stop Cooperativo",c:["Escucha","Cuerpo"],e:"ambos",a:"Edu",src:"guion_1301",d:"Se mueven con música. Si uno se para, todos se paran. Si uno imita una estatua (por ejemplo un mono), todos deben ser ese mono rápido. Escucha grupal: nadie puede repetir iniciativa hasta que hayan pasado todos.",v:"Quien se detiene, el resto lo imita y adopta su misma posición lo más rápido posible."},
{id:"foto-fija",t:"Foto fija",c:["Calentamiento","Personaje","Creatividad"],e:"ambos",a:"Edu",src:"guion_18",d:"Caminan libremente; al '¡Stop!' se congelan en una postura creativa. Se les pregunta quiénes son, qué hacen y cómo se sienten en esa posición.",v:"El resto se acopla al elemento congelado (unas tijeras, un árbol...)."},
{id:"esculturas-silencio",t:"Esculturas en silencio",c:["Calentamiento","Cuerpo","Creatividad"],e:"ambos",a:"Edu",src:"guion_14",d:"Con música se desplazan; al parar, cada uno busca pareja y forman juntos una escultura según la indicación del coach. Se reanuda la música y se repite con nuevas consignas."},
{id:"carrera-camara-lenta",t:"Carrera a cámara lenta",c:["Calentamiento","Cuerpo"],e:"ambos",a:"Edu",src:"guion_6",d:"Correr a cámara lenta; a la palmada se congelan (con temáticas: animales, dibujos, deportes, profesiones).",v:"Adultos: con la postura congelada dicen una pequeña intervención sobre un tema sugerido."},
{id:"estiramientos-creativos",t:"Estiramientos creativos",c:["Calentamiento","Cuerpo","Creatividad"],e:"ambos",a:"Edu",src:"guion_22",d:"Estirar el cuerpo imaginando: una flor que crece, un gato al sol, una nube que acaba en lluvia, una mariposa saliendo del capullo, una tortuga de su caparazón, exploradores submarinos."},
{id:"pies-a-cabeza",t:"Calentamiento de pies a cabeza",c:["Calentamiento","Cuerpo"],e:"ambos",a:"Edu",src:"guion_2001",d:"Calentamiento articular clásico desde los pies hasta la cabeza: tobillos, rodillas, cintura, hombros, brazos, muñecas, cuello."},
{id:"como-si",t:"Juego de movimiento «Como si...»",c:["Calentamiento","Cuerpo","Mímica"],e:"ambos",a:"Edu",src:"guion_3009 / Campamento",d:"Moverse como si el suelo quemara, hubiera viento fuerte, nieve, charcos gigantes, hielo resbaladizo, arena profunda; como si se llevara una bandeja llena, un globo tirara de la muñeca, se empujara un sofá... Alternar emociones sencillas.",v:"Dividir la clase en cámara lenta / normal / rápida."},
{id:"paseo-encuentros",t:"Paseo con emociones y encuentros",c:["Calentamiento","Emociones","Relación"],e:"ambos",a:"Edu",src:"guion_0710",d:"Caminamos con música; el facilitador da pautas y en los encuentros: ver a alguien que hace mucho que no ves, a alguien que odias, a alguien a quien no ubicas."},
{id:"ilusionometro",t:"Ilusionómetro (emociones no básicas)",c:["Emociones","Cuerpo"],e:"ambos",a:"Edu",src:"Dinámicas La Consti",d:"Moviéndonos por el espacio transitamos emociones: derrotado, ilusionado, fascinado, confusión, disgusto, vergüenza, asco, dolorido, curioso, celoso, deseo. Entre emoción y emoción se vuelve al neutro para hacer el cambio físico consciente."},
{id:"tiburones",t:"Juego de los tiburones",c:["Calentamiento","Energía"],e:"niños",a:"Edu",src:"guion_7",d:"El grupo 'nada' entre periódicos por el espacio. Al grito de '¡Cuidado, tiburones!' todos se suben a los periódicos o entran en el aro."},
{id:"ameba",t:"Ameba, peces, cocodrilo, gorila",c:["Calentamiento","Energía","Desinhibición"],e:"niños",a:"Edu",src:"guion_8",d:"Juego evolutivo: se empieza siendo ameba y con cada victoria en piedra-papel-tijera (o similar) se evoluciona a pez, cocodrilo y gorila, jugando cuerpo y sonido de cada animal."},
{id:"rio-colchonetas",t:"El río (colchonetas)",c:["Confianza","Escucha"],e:"niños",a:"Edu",src:"guion_23",d:"Los jugadores cruzan la pista subidos en una colchoneta pasándose otra por delante, sin tocar el suelo. Cooperación pura."},
{id:"lapices-grupo",t:"Llevar los lápices en grupo",c:["Concentración","Escucha","Confianza"],e:"niños",a:"Edu",src:"guion_1301",d:"En grupos de 4, transportar lápices sujetos entre las yemas de los dedos de unos y otros sin que se caigan."},
{id:"globos-nombres",t:"Juego de los globos",c:["Calentamiento","Escucha"],e:"niños",a:"Edu",src:"guion_11",d:"Cada uno escribe su nombre en dos globos. Todos a por sus globos, cronometrado. Después cada uno coge el primer globo que encuentra y se lo lleva a la persona del nombre: comparar tiempos (cooperar gana)."},
{id:"pelota-nombre",t:"Pelota al aire con nombre",c:["Calentamiento","Escucha"],e:"niños",a:"Edu",src:"guion_20",d:"Se lanza una pelota o globo al aire diciendo el nombre de otra persona, que debe correr a cogerla antes de que caiga."},
{id:"simon-dice",t:"Simón dice (teatral)",c:["Calentamiento","Escucha"],e:"niños",a:"Edu",src:"guion_7",d:"Simón dice clásico; los peques dictan por turnos y se juega con consignas teatrales."},
{id:"pañuelo-sombrero",t:"Juego del pañuelo con sombrero",c:["Calentamiento","Energía"],e:"niños",a:"Edu",src:"guion_0411",d:"El juego del pañuelo clásico pero con un sombrero como objeto a robar."},
{id:"naranja-manzana",t:"Naranja, manzana, banana",c:["Calentamiento","Concentración"],e:"niños",a:"Edu",src:"guion_1003",d:"En círculo mirando al compañero de la derecha con cuerpo y mirada. Naranja: 3 saltitos atrás; manzana: 3 saltitos atrás; banana: media vuelta. Las frutas las canta el profe."},
{id:"director-orquesta",t:"El director de orquesta",c:["Observación","Escucha"],e:"ambos",a:"Edu",src:"guion_8",d:"Uno sale de la sala. Se elige en secreto un director de orquesta que marca ritmos (palmas, gestos) que todos siguen y va cambiando. El que estaba fuera debe adivinar quién dirige.",v:"Uno sale y adivina quién lidera el movimiento del grupo."},
{id:"jeringuilla",t:"La jeringuilla",c:["Espacio","Escucha"],e:"niños",a:"Edu",src:"guion_2110",d:"Una persona va comprimiendo el escenario como el émbolo de una jeringuilla y el resto se comprime adaptándose al espacio que queda."},
{id:"ruiditos",t:"Ruiditos",c:["Voz","Calentamiento"],e:"ambos",a:"Edu",src:"Dinámicas La Consti",d:"Moviéndonos por el espacio hacemos sonidos con la boca sin parar según consignas: lluvia, viento, motor, teléfono, robot futurista, tren, guitarra eléctrica, patatas al masticar, sorber líquido, escoba, sartén hirviendo."},
{id:"vocales",t:"Hablar solo con vocales",c:["Voz","Comedia"],e:"ambos",a:"Edu",src:"guion_12",d:"Mantener conversaciones o escenas usando solo las vocales de las palabras. La intención y el paralenguaje sostienen el sentido."},
{id:"tren-vocales",t:"El tren de las vocales",c:["Voz","Ritmo"],e:"niños",a:"Edu",src:"guion_21_04",d:"Tren en círculo: cada uno es una vocal y la emite mientras el tren se mueve, para o acelera. A la palmada se intercambian las vocales."},
{id:"eco-griego",t:"Juego del eco (coro griego)",c:["Voz","Cuerpo"],e:"niños",a:"Edu",src:"guion_2110",d:"El docente dice una frase o emoción ('¡Oh, dioses poderosos!') y el grupo repite con su tono y gesto. Introducción al coro griego.",v:"Movimiento coral: caminar sincronizando pasos, respiración y ritmo; pisar fuerte todos a la vez."},
{id:"sonidos-cuerpo",t:"Los sonidos del cuerpo",c:["Voz","Cuerpo"],e:"niños",a:"Edu",src:"guion_24",d:"Explorar qué sonidos salen de la boca (suspiros, bostezos, silbidos, carcajadas, una moto), de las manos (palmas, chasquidos, frotar) y de los pies (taconear, zapatear)."},
{id:"motor-continuo",t:"BSO / Motor continuo",c:["Voz","Mímica"],e:"ambos",a:"Edu",src:"guion_17",d:"Como respirar: cada persona elige un motor (aspiradora, moto, cepillo de dientes eléctrico, motosierra) y sostiene su sonido de forma continua mientras acciona.",v:"Empezar una impro con un motor como disparador."},
{id:"tenis-frases",t:"Partido de tenis de frases",c:["Voz","Escucha","Ritmo"],e:"niños",a:"Edu",src:"guion_0212",d:"Dos equipos se 'pelotean' frases o palabras como en un partido de tenis, proyectando la voz de lado a lado."},
{id:"traductor-grito",t:"El traductor",c:["Voz","Comedia","Creatividad"],e:"niños",a:"Edu",src:"guion_0212",d:"Un niño dice una frase en idioma inventado; otro la traduce gritando claro al grupo. Libera creatividad y volumen."},
{id:"trovador",t:"Como un trovador",c:["Voz","Texto"],e:"adultos",a:"Edu",src:"guion_6",d:"Aprender y representar un texto poético breve jugando con música, ritmo e intención ('Se han desbocado los colores, gritaron los caracoles...')."},
{id:"1-2-3-palabras",t:"1, 2, 3... ¡palabra!",c:["Escucha","Creatividad"],e:"ambos",a:"Edu",src:"guion_17",d:"Por parejas, a la de tres ambos dicen una palabra a la vez. En la siguiente ronda intentan converger diciendo algo relacionado con las dos anteriores, hasta coincidir en la misma palabra."},
{id:"contar-100-miradas",t:"Contar hasta 100 sin desconcentrarse",c:["Concentración"],e:"ambos",a:"Edu",src:"guion_7",d:"Por parejas: uno cuenta del 1 al 100 en voz alta mirando al frente (o a los ojos); el otro, sin tocarle, intenta que se equivoque. Perder la mirada también es fallo."},
{id:"memoria-3-cambios",t:"Juego de la memoria (3 cambios)",c:["Observación","Concentración"],e:"ambos",a:"Edu",src:"Dinámicas La Consti",d:"Una persona se tapa los ojos; los demás realizan 3 cambios en la sala; debe adivinar qué ha cambiado.",v:"Fotografía del otro: observar a una persona al detalle y detectar 3 cambios en ella."},
{id:"memoria-espacial",t:"Memoria espacial",c:["Observación","Concentración"],e:"ambos",a:"Edu",src:"guion_20 / guion_1410",d:"Andamos por el espacio fijándonos en todo. A la señal cierran los ojos y el coach pregunta detalles de la sala y de los compañeros."},
{id:"espejo",t:"El espejo",c:["Observación","Escucha","Cuerpo"],e:"ambos",a:"Edu",src:"Dinámicas La Consti",d:"En parejas, uno es el espejo e imita todos los movimientos del otro.",v:"Con emociones; con temáticas (animales, deportes, profesiones); por turnos; espejo 'suave' donde el movimiento nace espontáneo sin líder claro; espejo caminando por la sala a 2 metros."},
{id:"sombra",t:"El juego de la sombra",c:["Observación","Cuerpo"],e:"ambos",a:"Edu",src:"guion_24",d:"Un actor va detrás de otro imitando todo lo que hace. Primero actúan normal, luego lo que quieran, y vuelta a lo normal."},
{id:"telefono-teatral",t:"Teléfono descompuesto teatral",c:["Mímica","Observación"],e:"niños",a:"Edu",src:"guion_3",d:"Cada niño transmite al siguiente una acción solo con mímica, sin hablar; el siguiente debe adivinarla y volver a transmitirla. Comparar el mensaje inicial y el final."},
{id:"doble-mirada",t:"Ejercicio de la doble mirada",c:["Observación","Relación"],e:"adultos",a:"Edu",src:"guion_6 / guion_7",d:"Trabajo de miradas por parejas o en círculo: buscar la mirada de alguien, y cuando dos miradas se encuentran, intercambiar el sitio sin dejar de mirarse.",v:"Desplazarse por la sala sin dejar de mirarse a los ojos."},
{id:"un-dos-tres-miradas",t:"Un dos tres, miradas (muertes teatrales)",c:["Desinhibición","Comedia"],e:"ambos",a:"Edu",src:"guion_15",d:"En círculo con los ojos cerrados; a la de 3 cada uno mira a alguien. Si dos miradas coinciden, mueren de forma teatral: te cae un rayo, infarto por emoción, te atragantas con una aceituna, explotas de risa, las palomas te confunden con pan..."},
{id:"guia-ciego",t:"El guía y el ciego",c:["Confianza","Espacio"],e:"ambos",a:"Edu",src:"guion_12",d:"Uno camina con los ojos cerrados y el otro le guía por los hombros. Después debe descubrir en qué parte de la sala está.",v:"Confianza en caída: dejarse caer hacia atrás y ser sostenido."},
{id:"evocacion-sensaciones",t:"Evocación de sensaciones",c:["Mímica","Emociones","Observación"],e:"ambos",a:"Edu",src:"guion_8",d:"Un participante ofrece a otro un vaso imaginario y éste bebe; a continuación se le dice el contenido y reacciona inmediatamente evocando el sabor.",v:"Percepción táctil: tocar algo caliente, frío, blando, pegajoso, espinoso; sabores dulce, amargo, ácido."},
{id:"si-y-ademas",t:"Sí, y además (cuento colectivo)",c:["Aceptación","Narrativa","Escucha"],e:"ambos",a:"Edu",src:"guion_12 / guion_3009",d:"En corro se construye un cuento entre todos: cada aportación acepta lo anterior y añade algo nuevo con 'sí, y además...'."},
{id:"si-a-huevo",t:"Sí a huevo",c:["Aceptación","Escucha"],e:"ambos",a:"Edu",src:"guion_17",d:"Una persona lanza una frase que debe ser aceptada por todos; el siguiente acepta y enriquece: 'Hoy puede ser un gran día' / 'Sí, y además vamos a la playa'.",v:"Escenas sin NO, sin PERO y sin PREGUNTAS: señora que cambia ropa sin ticket, abuelo con prenda manchada de tomate, entrevista de trabajo, cita Tinder, revisión de examen. Quien niega, sale justificando."},
{id:"si-vamos",t:"¡Sí, vamos!",c:["Aceptación","Energía"],e:"ambos",a:"Edu",src:"guion_3009",d:"Cualquiera grita una propuesta de acción ('¡vamos a nadar a un lago helado!', '¡bajemos esquiando la montaña!') y todo el grupo responde '¡SÍ, VAMOS!' y la hace con compromiso físico total.",v:"Por parejas por toda la sala, alternando las propuestas: 'Vamos a jugar al parchís' / '¡Sí, vamos!' (se acciona un poquito); ahora propone la otra: 'Vamos a tirar piedras por la ventana abierta' / '¡Sí, vamos!' (Ficha Jamming 28/09/2026)."},
{id:"palabra-a-palabra",t:"Historia palabra a palabra",c:["Aceptación","Escucha","Narrativa"],e:"ambos",a:"Edu",src:"guion_13",d:"Cada persona dice una palabra y entre todos se forma una historia: 'Esta', 'es', 'la', 'historia', 'de'..."},
{id:"mandar-aceptar",t:"Propuesta libre (mandar y aceptar)",c:["Aceptación","Escucha"],e:"adultos",a:"Edu",src:"guion_1410",d:"Por parejas, uno propone acciones sencillas ('lávate los dientes', 'túmbate') y el otro acepta accionando sin rechistar.",v:"Propuesta con una silla: pinta la silla, siéntate, escóndete tras ella."},
{id:"ni-no-ni-pero",t:"Ni no, ni pero, ni preguntas",c:["Aceptación"],e:"adultos",a:"Edu",src:"guion_7",d:"Escenas donde está prohibido decir no, pero y hacer preguntas. Quien lo hace, sale de escena justificando su salida y entra otro."},
{id:"hermano-palabra",t:"Hermano de palabra",c:["Aceptación","Escucha"],e:"adultos",a:"Edu",src:"guion_0710",d:"Dinámica de vínculo y aceptación por parejas: comprometerse con la palabra del otro y construir desde ella."},
{id:"autostop",t:"El autostop",c:["Aceptación","Personaje","Comedia"],e:"ambos",a:"Edu",src:"guion_7",d:"Un coche imaginario (con ruido de motor incluido) va recogiendo autoestopistas; cada persona que entra trae una idea genial para que el coche pare y un personaje cuya energía contagia a todo el vehículo."},
{id:"darle-un-uso",t:"Darle un uso (objeto real, utilidades imaginarias)",c:["Creatividad","Mímica"],e:"ambos",a:"Edu",src:"Dinámicas La Consti",d:"Con un objeto real (una botella, un palo, un diábolo) darle una utilidad distinta a la suya, creando otro objeto; los demás adivinan.",v:"El cubo que cobra vida: darle la vuelta a un cubo de basura y sacarle mil utilidades."},
{id:"caja-magica",t:"La caja mágica",c:["Mímica","Creatividad"],e:"niños",a:"Edu",src:"Dinámicas La Consti",d:"De una caja mágica imaginaria cada niño saca un objeto (real o imaginario) e interactúa con él; los demás lo adivinan.",v:"Caja real de objetos: sacar uno y crear un personaje a partir de él (físico, utilidad, de quién es)."},
{id:"invento-loco",t:"El invento loco",c:["Creatividad","Mímica"],e:"niños",a:"Edu",src:"Dinámicas La Consti",d:"Por parejas, con un objeto común (caja, silla, cuerda, pelota), transformarlo en algo completamente diferente (coche volador, máquina del tiempo, guitarra mágica) y representar cómo se usa.",v:"Mezclar dos objetos y defender el invento ante el público, que hace preguntas."},
{id:"objeto-importante",t:"El objeto importante",c:["Personaje","Narrativa","Emociones"],e:"ambos",a:"Edu",src:"guion_5",d:"De una bolsa de objetos, cada uno elige el suyo y cuenta dónde, cómo y por qué es tan importante para él, inventando su historia."},
{id:"silla-abuela",t:"La silla de mi abuela (objeto + secreto)",c:["Narrativa","Observación","Emociones"],e:"ambos",a:"Edu",src:"guion_0303",d:"Uno dice algo sencillo ('la silla de mi abuela'); el segundo lo describe ('tela marrón, desgaste abajo'); el tercero dice para qué sirve o qué causa, escondiendo un pequeño secreto o momento ('sirve para sentarse mientras cose los pantalones de mi abuelo')."},
{id:"maleta-pesada",t:"Puertas y maleta pesada (punto fijo)",c:["Mímica","Cuerpo"],e:"ambos",a:"Edu",src:"guion_6",d:"Trabajo de punto fijo: abrir todo tipo de puertas (pomo, corredera, de quirófano) y cargar una maleta pesadísima que no se mueve. Los objetos imaginarios tienen peso, tamaño y sitio."},
{id:"camion-mudanzas",t:"El camión de mudanzas",c:["Mímica","Escucha","Espacio"],e:"ambos",a:"Edu",src:"guion_8",d:"Entre todos descargamos un camión imaginario sin chocarnos: el coach dicta los objetos (un frigorífico, una lavadora, una lámpara altísima, un sofá...). Los tamaños y pesos deben ser coherentes entre todos.",v:"Versión navideña: descargar el trineo de regalos."},
{id:"construir-espacio-ciegas",t:"Construir un espacio a ciegas",c:["Espacio","Observación","Confianza"],e:"ambos",a:"Edu",src:"guion_12",d:"La mitad de la clase construye un espacio sonoro y físico; la otra mitad, con ojos cerrados, debe descubrir dónde está (lugar, estación del año, época histórica)."},
{id:"cuatro-zonas",t:"Las 4 zonas emocionales",c:["Espacio","Emociones"],e:"ambos",a:"Edu",src:"guion_7",d:"La sala se divide en 4 zonas, cada una con una emoción. La improvisación cambia de tono al cruzar de zona, con una palabra del público como disparador."},
{id:"space-walk",t:"Space Walk / Caminata espacial",c:["Cuerpo","Concentración","Mímica"],e:"ambos",a:"Edu",src:"guion_1410 / guion_10",d:"Caminar como si flotáramos por el espacio, sin gravedad, con movimiento consciente y cuidadoso. El coach añade consignas: gravedad lunar, tormenta de meteoritos, campo magnético a cámara lenta."},
{id:"maleta-polo",t:"La maleta para el Polo Norte",c:["Mímica","Creatividad"],e:"niños",a:"Edu",src:"guion_6",d:"Preparar entre todos la maleta imaginaria para una expedición al Polo Norte, decidiendo y mimando cada objeto. Después, foto grupal en el Polo."},
{id:"raccord",t:"Ejercicio de raccord",c:["Observación","Texto"],e:"adultos",a:"Edu",src:"guion_2110",d:"Trabajo de continuidad como en cine: repetir una escena manteniendo posiciones, objetos (una botella), pasos, marcas en el suelo y vestuario exactamente iguales."},
{id:"juego-emociones",t:"El juego de las emociones",c:["Emociones","Mímica"],e:"niños",a:"Edu",src:"Dinámicas La Consti",d:"Representar emociones (feliz, triste, enfadado, asustado) sin palabras; los demás adivinan cuál es.",v:"Mímica de emociones frente al espejo, usando solo rostro y voz."},
{id:"escalera-emocional",t:"Escalera emocional facial",c:["Emociones","Cuerpo"],e:"ambos",a:"Edu",src:"guion_25",d:"Desde neutro, subir progresivamente la intensidad de una emoción solo con el rostro, del 1 al 10: enfado 1 (casi nada), 5 (visible), 10 (explosivo)."},
{id:"cambio-polaridad",t:"Cambio de polaridad",c:["Emociones","Concentración"],e:"ambos",a:"Edu",src:"guion_25",d:"Empezar una acción simple (doblar ropa) en neutro. El director grita una emoción ('¡Furia!', '¡Éxtasis!') y hay que cambiar al instante sin abandonar la acción."},
{id:"accion-grados",t:"Acción en grados (de menos a más)",c:["Emociones","Cuerpo"],e:"ambos",a:"Edu",src:"guion_13",d:"Uno realiza una acción y otro espera detrás; a la voz de cambio, el segundo continúa la misma acción con unos grados más de intensidad. De menos a más, y luego al revés.",v:"Con porcentajes: la misma acción al 10%, 50% y 80% de exageración."},
{id:"risa-llanto",t:"De la risa al llanto",c:["Emociones","Cuerpo"],e:"adultos",a:"Edu",src:"guion_6",d:"Pasar de la risa al llanto manteniendo la misma corporalidad: solo cambia la emoción, no el cuerpo."},
{id:"7-niveles-tension",t:"Los 7 niveles de tensión",c:["Cuerpo","Emociones"],e:"adultos",a:"Edu (Lecoq)",src:"guion_15",d:"Explorar los niveles: 1 cuerpo muerto, 2 relajado, 3 neutral, 4 curiosidad, 5 emergencia, 6 crisis, 7 explosión. Transitar entre ellos con voz o música; luego escenas con niveles distintos por personaje (uno en 2, otro en 6) o subiendo todos del 1 al 7.",v:"Con ejemplos cotidianos: 'nivel 3: esperando el bus', 'nivel 6: persiguiendo a un ladrón'."},
{id:"miedos-estupidos",t:"Miedos a cosas que no dan miedo",c:["Comedia","Personaje","Emociones"],e:"adultos",a:"Edu",src:"guion_1410",d:"Cada uno se inventa un miedo absurdo (miedo a pasar de moda, a las colecciones de sellos...) y lo expone y exagera en un pequeño monólogo."},
{id:"cuerpo-pincel",t:"El cuerpo como pincel",c:["Cuerpo","Emociones","Creatividad"],e:"adultos",a:"Edu",src:"guion_25",d:"Imaginar que el cuerpo es un pincel gigante que pinta en el aire líneas, curvas y espirales; después pintar con distintas emociones. El cuerpo se vuelve narrativo sin palabras."},
{id:"imitar-globo",t:"Imitar a un globo",c:["Cuerpo","Observación"],e:"niños",a:"Edu",src:"guion_20",d:"Por parejas: uno infla un globo físico y el otro lo imita corporalmente; cuando se desinfla, puede llegar hasta el suelo."},
{id:"figuras-corporales",t:"Figuras con el cuerpo",c:["Cuerpo","Escucha"],e:"niños",a:"Edu",src:"guion_0411",d:"Andando por el espacio, formar entre todos figuras: una línea, un cuadrado, un círculo.",v:"Con emociones donde todos deben coincidir."},
{id:"mercado-personajes",t:"Mercado de personajes",c:["Personaje","Creatividad"],e:"ambos",a:"Edu",src:"guion_11",d:"Cada uno imagina y dibuja un personaje. En círculo, prepara al compañero como ese personaje (cómo habla, cómo se mueve, qué lleva) y luego lo 'vende' al resto como si fuera un anuncio."},
{id:"fiesta-cumpleanos",t:"Quién viene a mi fiesta",c:["Personaje","Comedia","Formato con público"],e:"ambos",a:"Edu",src:"guion_0710",d:"Un anfitrión sale de la sala. Los invitados pactan cada uno una peculiaridad secreta (física, emocional, de personaje). Van llegando a la fiesta de uno en uno y el anfitrión debe adivinar cada peculiaridad; al acertar, el invitado sale.",v:"Adivina el personaje (Toto): adivinar 2 características de cada invitado; personajes muy exagerados y marcados."},
{id:"personaje-terrorifico",t:"Creación de personaje (con material)",c:["Personaje","Creatividad"],e:"ambos",a:"Edu",src:"guion_2",d:"Crear un personaje (por ejemplo terrorífico en Halloween) con material y vestuario: ¿cuántos años tiene? ¿qué objetivo vital? ¿quién es su antagonista? ¿qué le mueve? ¿qué infancia tuvo? Calentar dándole cuerpo, mirada y estatus, y presentarlo en monólogo ante el resto, que puede preguntar."},
{id:"entradas-monstruosas",t:"Entradas monstruosas",c:["Personaje","Desinhibición"],e:"niños",a:"Edu",src:"guion_2810",d:"Uno a uno entran al centro con una acción propia de su personaje (terrorífico o no) mientras el resto adivina qué tipo de personaje es.",v:"Con un objeto sobrenatural creado en clase."},
{id:"personaje-agrandado",t:"El personaje agrandado",c:["Personaje","Comedia","Aceptación"],e:"adultos",a:"Edu",src:"guion_8",d:"Uno crea un personaje con carácter y emoción; sale otro y hace el mismo personaje más grande, más exagerado. Y así sucesivamente."},
{id:"animales-cuerpo",t:"Animales por partes del cuerpo",c:["Personaje","Cuerpo","Estatus"],e:"ambos",a:"Edu",src:"guion_2402",d:"Caminar guiados por una parte del cuerpo asociada a un animal: pecho-águila/rey (seguridad, mandar sin gritar), frente-león (pensar, estrategia), pelvis-hiena (instinto, risa, caos), pies-zorro/gato callejero (astucia, sigilo)."},
{id:"desfile-animales",t:"El gran desfile de animales",c:["Personaje","Cuerpo","Comedia"],e:"niños",a:"Edu",src:"guion_10",d:"Equipos de animales (elefantes, monos, pingüinos) preparan su forma de moverse, gestos y sonidos, eligen música y desfilan por un pasillo. Después, encuentros: ¿cómo se saludan un elefante y un mono?"},
{id:"que-eres",t:"¿Qué eres?",c:["Creatividad","Escucha","Espacio"],e:"niños",a:"Edu",src:"guion_21_Serranillos",d:"Nos movemos con música; al parar, el coach dice un nombre y le pregunta '¿qué eres?'. Responde ('¡una tostadora!') y los demás se acoplan construyendo la imagen alrededor."},
{id:"juego-foto",t:"El juego de la foto",c:["Creatividad","Espacio","Escucha"],e:"ambos",a:"Edu",src:"Dinámicas La Consti",d:"En 10 segundos todos imitan un componente de una imagen dada (un bosque: uno es árbol, otra ardilla, otra el sol), congelados; después dicen qué son.",v:"La foto viva: la foto cobra vida y se mueve hasta hacer una mini escena; foto de familias (rica, pobre, de verduras...) que arranca a la acción con un botón."},
{id:"cuadro-foto-escena",t:"Del cuadro a la escena",c:["Creatividad","Narrativa"],e:"ambos",a:"Edu",src:"guion_2701",d:"Dos grupos: con un título, cada grupo crea un cuadro estático (foto). Después cada equipo planifica y representa una escena donde en algún momento ocurra exactamente esa foto."},
{id:"fotos-secretas",t:"Fotos secretas",c:["Narrativa","Observación"],e:"ambos",a:"Edu",src:"guion_20",d:"Preparar una escena donde una persona encuentra fotos que esconden secretos; el resto tiene que adivinar qué revelan.",v:"Dos personas preparan 3 fotos congeladas y el público adivina la historia."},
{id:"camara-fotos-vacaciones",t:"Recuerdos: la cámara de fotos",c:["Narrativa","Creatividad","Emociones"],e:"ambos",a:"Edu",src:"Dinámicas La Consti",d:"Cada uno saca su cámara imaginaria y cuenta las 5 fotos de sus vacaciones con todo detalle: quién estaba, el lugar, qué se celebraba.",v:"El público elige una foto y el dueño dirige su representación con los compañeros."},
{id:"profes-expertos",t:"Profes de lo que sabemos",c:["Personaje","Voz","Comedia"],e:"ambos",a:"Edu",src:"guion_15",d:"Cada uno da una clase magistral de algo que sepa mucho, adaptándose al público que marca el coach: gente muy mayor, niños pequeños, reyes, extraterrestres, espías (susurrando en código), un público que se duerme."},
{id:"saludo-publico",t:"Saludo al público",c:["Personaje","Desinhibición","Voz"],e:"ambos",a:"Edu",src:"guion_22",d:"Saludar al público como: un rey dando un discurso, un robot recién encendido, un mago, una estrella de rock, un chef, piratas convenciendo a un pueblo de que no les maten, actor agradeciendo un Óscar."},
{id:"cotidiano-extremista",t:"Cotidiano extremista",c:["Comedia","Personaje","Creatividad"],e:"adultos",a:"Edu",src:"guion_1410",d:"Nombrar personajes cotidianos (un abuelo, una peluquera, un sacerdote) y relacionarlos con su extremo exagerado para abrir el abismo hacia la comedia: un sacerdote paranoico con los ovnis, una cocinera con alergia a cocinar para mayores."},
{id:"peor-forma",t:"La peor forma de...",c:["Comedia","Creatividad"],e:"adultos",a:"Edu",src:"guion_23",d:"Representar la peor forma posible de: dar una noticia médica, ver al bebé de un amigo, animar una fiesta infantil, pedir una cita, una entrevista de trabajo, un anuncio, disculparse."},
{id:"3-formas",t:"3 formas de hacer algo",c:["Creatividad","Comedia"],e:"adultos",a:"Edu",src:"guion_22",d:"Mostrar tres formas distintas de: abrir una puerta, reaccionar al ganar la lotería, comer una manzana, bailar en una fiesta, dejar a tu pareja, robar a alguien."},
{id:"que-no-haria",t:"Qué no haría o diría nunca",c:["Comedia","Personaje"],e:"ambos",a:"Edu",src:"guion_13",d:"Representar lo que NUNCA haría o diría un personaje tipo: un papá, una mamá, un profesor. La ruptura de expectativa es el motor cómico."},
{id:"quien-soy-cartel",t:"¿Quién soy? (cartel en la espalda)",c:["Personaje","Estatus","Observación"],e:"niños",a:"Edu",src:"guion_2402",d:"Cada uno lleva un cartel en la espalda con un personaje (príncipe pensador, fantasma, rey, princesa triste, duende travieso...) que no conoce. El grupo le trata según el cartel (reverencias, miedo, admiración) y debe adivinar quién es."},
{id:"shakespearizate",t:"Shakespearízate",c:["Personaje","Cuerpo","Texto"],e:"niños",a:"Edu",src:"guion_0303",d:"Movimiento por el espacio con consignas progresivas de mundo shakespeariano: castillo frío de piedra, noble engreído, fantasma que flota, bufón del rey, Hamlet que duda cada paso. Después sonidos de época: tambor de guerra, trompeta real, cadenas, público isabelino abucheando."},
{id:"circulo-magico",t:"Círculo mágico de personajes",c:["Personaje","Narrativa"],e:"niños",a:"Edu",src:"guion_2810",d:"Sentados en círculo, cada niño presenta a su personaje: cómo se llama, de dónde viene, cuál es su mayor miedo o poder especial. Después: cómo se movería, cómo saludaría, cómo pediría una hamburguesa."},
{id:"pocima-personaje",t:"La pócima de personajes",c:["Personaje","Creatividad","Narrativa"],e:"niños",a:"Edu",src:"guion_2810",d:"Entre todos se crea un personaje por ingredientes: uno da el nombre, otro el apellido, la edad, algo que le encanta, algo que odia, dónde y con quién vive. Se mezclan en la pócima y se hace una impro de 3 personas alrededor de ese personaje."},
{id:"monologo-objetos",t:"Monólogo con objetos",c:["Personaje","Narrativa","Emociones"],e:"adultos",a:"Edu",src:"guion_25",d:"Elegir 3 objetos al azar y crear un monólogo que los relacione ('este zapato me recuerda al día que...')."},
{id:"monologo-acciones",t:"Monólogo con acciones",c:["Personaje","Mímica"],e:"ambos",a:"Edu",src:"guion_29",d:"Monólogo de uno en uno sosteniendo una acción física continua que alimente el relato."},
{id:"actings",t:"Actings con tarjetas",c:["Texto","Personaje","Emociones"],e:"ambos",a:"Edu",src:"guion_12",d:"Monólogos preparados desde una premisa: el superhéroe que pierde su capa, la fiesta sin pastel, la mascota perdida, el científico loco... Para adultos: la llamada con mala noticia, la presentación que sale mal, la videollamada de la herencia, la nota del examen, el debate con los padres. Con foco en transición emocional, pausa, escucha interna y verdad."},
{id:"reacciones-presentadas",t:"Reacciones presentadas",c:["Relación","Emociones","Escucha"],e:"ambos",a:"Edu",src:"guion_14",d:"Dos personas frente a frente muy cerca; una tercera al lado dice quiénes son y qué les pasa. Los dos solo reaccionan mirándose, con rostro, cabeza y cuello expresivos."},
{id:"aumento-sueldo",t:"Pedir un aumento de sueldo",c:["Objetivo","Comedia","Personaje"],e:"adultos",a:"Edu",src:"guion_28",d:"Un empleado va al despacho del jefe a pedir un aumento, con pautas de estado: enamorado, metido de coca, triste, recién salido de un funeral, místico."},
{id:"regreso-hogar",t:"El regreso al hogar",c:["Narrativa","Emociones","Personaje"],e:"adultos",a:"Edu",src:"guion_10",d:"Un lugar al que la gente vuelve tras una larga ausencia. Cada personaje define: quién es, de dónde viene, a quién encuentra al volver y cómo siente esa vuelta (alivio, culpa, ansiedad)."},
{id:"grinch",t:"Los villanos de la Navidad",c:["Objetivo","Personaje","Comedia"],e:"ambos",a:"Edu",src:"guion_9_navidad",d:"Personajes villanos navideños (el Grinch, un duende gruñón, un árbol que odia las luces) improvisan una reunión para boicotear la Navidad. El Grinch debe convencer con sutileza; a mitad de impro puede ser convencido él o convencer al resto, siempre justificado."},
{id:"cuento-inventado",t:"Cuento inventado (círculo)",c:["Narrativa","Escucha"],e:"ambos",a:"Edu",src:"Dinámicas La Consti",d:"Sentados en círculo, uno empieza un cuento y tras unas frases el siguiente lo continúa, aceptando todo lo anterior.",v:"Cuento continuado con señal del director."},
{id:"narrador-mudo",t:"El narrador mudo",c:["Narrativa","Mímica","Escucha"],e:"ambos",a:"Edu",src:"Dinámicas La Consti",d:"Una persona narra lo que pasa entre dos personajes, y esos personajes interpretan la historia interactuando sin hablar."},
{id:"narradores-interpretes",t:"Narradores e intérpretes",c:["Narrativa","Escucha"],e:"ambos",a:"Edu",src:"guion_2",d:"Dos o tres narran una historia por turnos (una o dos frases cada vez) y el resto la interpreta y acciona despreocupándose de la narración.",v:"Con final secreto dado por el coach ('muere por un oso'): los narradores deben llevar la historia hasta él."},
{id:"palabras-congeladas",t:"Palabras congeladas en diálogos",c:["Narrativa","Concentración"],e:"adultos",a:"Edu",src:"guion_3",d:"En parejas, hacer una impro donde deben aparecer 5 palabras memorizadas antes, integradas con naturalidad.",v:"Sombrero de palabras: el público escribe palabras que los actores sacan y justifican en mitad de la escena."},
{id:"drama-congelado",t:"Drama congelado",c:["Narrativa","Concentración"],e:"ambos",a:"Edu",src:"guion_8",d:"Dos parejas alternan: una impro arranca y al '¡congelados!' del coach se congela y arranca la otra pareja con una escena completamente distinta. Las historias avanzan en paralelo sin cruzarse."},
{id:"rebobinar",t:"Rebobinar (final primero)",c:["Narrativa","Formato con público"],e:"ambos",a:"Edu",src:"guion_30",d:"Se da un final y la impro se construye rebobinando escenas hacia atrás, revelando cómo se llegó hasta ahí. Con presentación de personajes, nudo con conflicto y desenlace en 3 escenas.",v:"Final Primero (Sara): la primera escena ES el final impactante y las siguientes explican el rompecabezas; al final se repite la primera escena con significado nuevo."},
{id:"impro-estilos",t:"Impro por estilos de película",c:["Comedia","Narrativa","Formato con público"],e:"ambos",a:"Edu",src:"guion_11",d:"La misma escena o historia jugada en estilos: Disney, terror, acción, catástrofe, ciencia ficción, telenovela, cine argentino, oeste, cine negro, Marvel, mudo, musical..."},
{id:"otra-mas-menos",t:"Otra, más, menos",c:["Escucha","Comedia"],e:"ambos",a:"Edu",src:"guion_12",d:"En mitad de la escena el coach dice 'otra' (reformular la última frase), 'más' (subir la intensidad) o 'menos' (bajarla). Obliga a escucharse y produce momentos muy cómicos."},
{id:"descripcion",t:"¡Descripción!",c:["Narrativa","Observación"],e:"ambos",a:"Edu",src:"guion_24",d:"En mitad de una impro el coach grita '¡DESCRIPCIÓN!' y el improvisador debe describir al detalle el objeto o la situación que esté tocando o viviendo, y seguir."},
{id:"subtitulos",t:"Subtítulos imaginarios / Gibberish con traductor",c:["Comedia","Voz","Escucha"],e:"ambos",a:"Edu",src:"guion_18",d:"Dos actúan una escena en idioma inventado; otros dos, fuera, traducen lo que dicen en tiempo real.",v:"El traductor doble; doblaje: dos actúan moviendo la boca y otros dos les ponen la voz desde el lateral."},
{id:"impro-1min",t:"Impro de 1 minuto, 30 segundos y 10 segundos",c:["Narrativa","Comedia","Ritmo"],e:"ambos",a:"Edu",src:"guion_18",d:"Se improvisa una escena en 1 minuto; se repite la misma en 30 segundos; y por último en 10. Síntesis, ritmo y memoria."},
{id:"experto-3-cabezas",t:"El experto de 3 cabezas",c:["Escucha","Comedia","Formato con público"],e:"ambos",a:"Edu",src:"guion_22",d:"Tríos que actúan como un solo experto respondiendo preguntas absurdas del público ('¿cómo se construye un castillo en el aire?'), una palabra por cabeza."},
{id:"expert-double",t:"Doble experto (apuntado)",c:["Comedia","Escucha"],e:"ambos",a:"Edu",src:"guion_25",d:"Un actor responde preguntas del público como experto en un tema absurdo (criar jirafas en el espacio), pero otro actor detrás le susurra las respuestas."},
{id:"apuntador",t:"El apuntador",c:["Comedia","Escucha"],e:"ambos",a:"Edu",src:"guion_22",d:"Escena donde un apuntador externo dicta frases que los actores deben incorporar tal cual en cuanto las oyen."},
{id:"cual-es-tu-excusa",t:"¿Cuál es tu excusa?",c:["Comedia","Escucha","Mímica"],e:"ambos",a:"Edu",src:"guion_24",d:"Una persona se sienta y dos (papás o policías) la atosigan. Detrás de ellos, un cómplice gesticula la excusa y el interrogado la va 'leyendo' e improvisando en voz alta."},
{id:"roba-la-frase",t:"Roba la frase (buzzer)",c:["Escucha","Comedia"],e:"ambos",a:"Edu",src:"guion_2701",d:"En grupos de 4 con buzzer: al sonar, robar la última frase dicha por el compañero y reinventar su significado en la propia historia."},
{id:"tostadora",t:"La tostadora",c:["Narrativa","Ritmo","Formato con público"],e:"ambos",a:"Edu",src:"guion_18",d:"Formato de escenas cortas que 'saltan' como tostadas: a la palmada (o con palabras del público como guía), cambia la escena o se reformula."},
{id:"cambio-roles-pollo",t:"Cambio de roles (con el pollo)",c:["Personaje","Escucha"],e:"ambos",a:"Edu",src:"guion_3",d:"En parejas, escena en marcha: al sonar el pollo (o palmada o timbre) los improvisadores se intercambian los personajes y siguen.",v:"Personajes super raros con cambio a la palmada."},
{id:"voz-detras",t:"La voz de detrás (doblaje humano)",c:["Escucha","Mímica","Comedia"],e:"ambos",a:"Edu",src:"guion_4",d:"Una persona se pone detrás y habla; la de delante solo acciona y pone el cuerpo: son la misma persona. Sincronizar intención, gesto y palabra.",v:"Impros a 4 donde dos hablan a la vez siendo un solo personaje, y viceversa."},
{id:"historia-apartados",t:"La historia por apartados",c:["Narrativa","Escucha"],e:"adultos",a:"Edu",src:"guion_4",d:"Cada persona se encarga de un apartado de la historia: una describe personajes, otra el lugar, otra las acciones, otra las emociones. Entre todas tejen el relato."},
{id:"pelota-historia",t:"La pelota que habla",c:["Narrativa","Escucha"],e:"niños",a:"Edu",src:"guion_7",d:"Se construye una historia donde solo puede hablar quien tiene la pelota; otra persona solo actúa lo narrado."},
{id:"historias-sonidos",t:"Historias con sonidos",c:["Narrativa","Voz","Escucha"],e:"niños",a:"Edu",src:"guion_18",d:"Un niño cuenta una historia y en ciertos momentos los demás hacen los sonidos que la acompañan (olas, viento, un monstruo rugiendo)."},
{id:"deja-que-te-cuente",t:"Déjame contarte el viaje loco a...",c:["Narrativa","Aceptación","Comedia"],e:"adultos",a:"Edu",src:"guion_9_navidad",d:"Alguien lanza la premisa ('déjame contarte la primera vez que me tiré en paracaídas') y los compañeros rellenan la historia colectivamente desde esa primera frase."},
{id:"pregunta-impro",t:"Preguntas y motores",c:["Narrativa","Escucha"],e:"ambos",a:"Edu",src:"guion_16",d:"Sentados en círculo: una persona hace una pregunta a otra, ésta contesta y pregunta a una tercera. Entre pregunta y pregunta, dos personas improvisan con esos datos: se improvisa con los motores, no tanto con las personas."},
{id:"narracion-cabezas",t:"Narración con toque de cabeza",c:["Narrativa","Escucha"],e:"ambos",a:"Edu",src:"guion_1301",d:"Cuatro personas sentadas y el coach detrás: empieza una narración y solo puede hablar aquella a la que toca la cabeza, continuando exactamente donde iba la historia."},
{id:"asociacion-ultimo",t:"Lo relacionado con lo último",c:["Escucha","Creatividad"],e:"ambos",a:"Edu",src:"guion_30",d:"Van saliendo de uno en uno: el primero dice lo que es ('una señal de stop'); el siguiente dice algo relacionado SOLO con lo último dicho, no con lo anterior. Cadena de asociación libre."},
{id:"21-dias",t:"21 días (reality)",c:["Formato con público","Personaje","Narrativa"],e:"adultos",a:"Edu",src:"guion_8",d:"La clase se divide en dos grupos; cada uno pacta 5 minutos quién presenta y dónde (un hotel del Imserso...). Hay personajes fijos (entrevistador, dueño, cocinero) y el resto entra y sale, estilo reality documental."},
{id:"autobus",t:"El autobús",c:["Personaje","Espacio"],e:"ambos",a:"Edu",src:"guion_2001",d:"La gente entra y sale de un autobús; cada uno con un personaje muy distinto que entra con su acción característica."},
{id:"fiesta-monstruos",t:"Fiesta de personajes (máximo 3 en escena)",c:["Personaje","Escucha","Formato con público"],e:"ambos",a:"Edu",src:"guion_2",d:"Fiesta colectiva donde se entra y se sale de escena libremente, pero nunca puede haber más de 3 personas a la vez: gestión de foco, entradas y salidas justificadas."},
{id:"ganar-atencion",t:"Ganar la atención del público",c:["Desinhibición","Comedia"],e:"adultos",a:"Edu",src:"guion_17",d:"La sala se divide en dos espacios con un improvisador en cada uno. Cada improvisador hace lo que quiera para ganarse la atención del público, que cada 2 segundos señala a quién está mirando."},
{id:"escena-isla",t:"La escena de la isla",c:["Narrativa","Relación"],e:"adultos",a:"Edu",src:"guion_3",d:"Escena larga tipo isla desierta: convivencia, conflicto y evolución de personajes en un espacio cerrado."},
{id:"dobladores",t:"Dobladores de películas",c:["Voz","Comedia","Escucha"],e:"niños",a:"Edu",src:"guion_21_04",d:"En parejas: uno hace mímica exagerada de una escena dramática (rescate, tesoro, monstruo) y el otro le dobla la voz en tiempo real, jugando volúmenes, agudos y graves."},
{id:"idioma-inventado",t:"Idioma inventado",c:["Voz","Creatividad"],e:"ambos",a:"Edu",src:"guion_21_04",d:"En grupos de 3, representar una escena cotidiana (cole, mercado, el espacio) hablando en idioma inventado: que se entienda qué pasa solo por la intención de la voz."},
{id:"gesto-recorrido",t:"El gesto en el recorrido",c:["Cuerpo","Ritmo","Escucha"],e:"niños",a:"Edu",src:"guion_0411",d:"Grupos de 3-4. El primero crea un gesto en un recorrido de un punto a otro; los demás lo repiten al pasar; en cada ronda el siguiente añade otro gesto. Al final se representan mezclando los recorridos entre grupos."},
{id:"coro-rombo",t:"El coro del rombo (historia con motor)",c:["Voz","Narrativa","Cuerpo"],e:"niños",a:"Edu",src:"guion_0411",d:"Cuatro en rombo; quien está en cabecera arranca una historia con un motor y dice 3 frases cortas que el coro repite en voz muy alta. El coro se desmonta, se escenifica lo contado, y se vuelve al rombo rotando la cabecera."},
{id:"reino-encantado",t:"El Reino Encantado",c:["Narrativa","Personaje","Creatividad"],e:"niños",a:"Edu",src:"guion_16",d:"Escenario imaginario donde los niños, según sus disfraces o personajes, habitan un reino. Se les da un conflicto sencillo (el rey perdió su corona, la bruja lanzó un hechizo) y deben improvisar juntos la solución."},
{id:"fuga-jardin",t:"La fuga del jardín oscuro",c:["Cuerpo","Narrativa","Concentración"],e:"niños",a:"Edu",src:"guion_20",d:"Prisioneros en un jardín encantado custodiado por un vigilante mágico: moverse sigilosamente interpretando personajes que intentan escapar. Al ser detectados, retroceden y dramatizan su captura."},
{id:"huevo-pascua",t:"La historia de los huevos de Pascua",c:["Narrativa","Creatividad"],e:"niños",a:"Edu",src:"guion_24",d:"Inventar una historia de encontrar 4 huevos de Pascua diferentes en 4 escenas diferentes."},
{id:"conciencia",t:"Impro con conciencias",c:["Narrativa","Escucha","Comedia"],e:"ambos",a:"Edu",src:"guion_24",d:"Escena donde algunos jugadores hacen de conciencia de los personajes, verbalizando en voz alta lo que piensan de verdad mientras los personajes actúan."},
{id:"sepia",t:"El juego de la sepia",c:["Personaje","Creatividad"],e:"adultos",a:"Edu",src:"guion_15",d:"Con temáticas: ¿quién eres y qué está pasando? Jugar interacciones entre compañeros desde imágenes propuestas."},
{id:"escena-input",t:"Escena desde un input de 4 palabras",c:["Narrativa","Creatividad"],e:"ambos",a:"Edu",src:"guion_3009",d:"Con un input de 3-4 palabras, el grupo tiene 10 minutos para preparar una obra breve con presentación, conflicto y resolución, y la expone."},
{id:"regalo-inesperado",t:"El regalo inesperado (escena en un minuto)",c:["Narrativa","Creatividad"],e:"niños",a:"Edu",src:"guion_1301",d:"Tarjetas con lugar + caja misteriosa + conflicto: el Robot-Niñera que da órdenes, el mando que congela gente en el museo, el libro que susurra el futuro, el temporizador que acelera el tiempo, el horario mágico de la escuela al revés."},
{id:"sevillanas-inventadas",t:"Las sevillanas de...",c:["Cuerpo","Ritmo","Comedia"],e:"ambos",a:"Edu",src:"guion_20",d:"Se elige un país o tema; entre cinco personas se inventan los pasos (movimiento + ruido o voz). Después todos a la vez bailan 'las sevillanas de...' tomando la iniciativa grupal por turnos."},
{id:"baile-competitivo",t:"Baile competitivo",c:["Desinhibición","Energía","Cuerpo"],e:"ambos",a:"Edu",src:"guion_16",d:"Dos grupos se enfrentan bailando con músicas diferentes: rock, dance, sevillanas. Gana la entrega, no la técnica."},
{id:"regla-nueve",t:"La regla del nueve (matar al editor feroz)",c:["Creatividad","Desinhibición"],e:"adultos",a:"Edu (Improv Handbook)",src:"guion_30",d:"Escribir 10 nombres inventados de equipos divertidos, sin filtro. De cada diez ideas, nueve serán basura y no pasa nada: se escribe sin riesgo ni carga, sin esperanza ni temor. Reduce aspiraciones, piensa en el proceso y aplaude cada pequeña victoria."},
{id:"ranita",t:"Relajación de la ranita",c:["Relajación"],e:"niños",a:"Edu",src:"guiones niños",d:"Relajación guiada de atención plena para peques (la ranita respira y observa). Para bajar la energía al final o en mitad de la clase.",v:"Relajación del paseo por la playa; tumbados con un objeto en el pecho que no se puede caer."},
{id:"frase-final",t:"Frase final",c:["Narrativa","Objetivo"],e:"ambos",a:"Edu",src:"guion_28_04",d:"Se da al inicio de la escena la frase exacta con la que tiene que terminar. Da un objetivo claro y encanta a los peques."},
// ==== JUEGOS TAMBIÉN USADOS EN IMPROXPRESIÓN (doble origen) ====
{id:"que-haces",t:"¿Qué haces? / ¿Qué estás haciendo?",c:["Mímica","Escucha","Creatividad"],e:"ambos",a:"Edu / Toto Curcio",src:"Dinámicas La Consti / HSP",d:"Uno realiza una acción clara. Otro pregunta '¿qué haces?' y el primero responde una acción totalmente diferente a la que hace: el que preguntó pasa a realizar esa nueva acción. Lento y claro: no se pregunta hasta entender la acción.",v:"La persona que acciona dice al oído del que pregunta la siguiente acción; versión '¿cómo te hace sentir?'."},
{id:"4-elementos-lecoq",t:"Los 4 elementos de Lecoq",c:["Personaje","Cuerpo"],e:"ambos",a:"Edu (Lecoq)",src:"guion_17 / MasterClass Edu Ferrés",d:"Transitar los elementos: Fuego (explosivo, pasional, caótico), Agua (fluido, adaptable, emocional), Tierra (firme, lento, protector), Aire (ligero, disperso, impredecible). Primero cuerpo, luego voz, luego personaje con estatus.",v:"Personaje híbrido: en parejas, de espaldas, cada uno combina dos elementos; a la señal se giran y se encuentran por primera vez. Impro de 5 minutos."},
{id:"vida-personaje",t:"Vida de un personaje",c:["Personaje","Narrativa"],e:"ambos",a:"Edu",src:"guion_13 / Ficha Jamming 03/02/2025",d:"Representar la vida de un personaje en tres actos (pequeño, adulto, anciano) con un hobby, un trabajo y una familia.",v:"Versión escénica: 4 improvisadores realizan acciones simultáneas sin hablar; el público elige protagonista y se construyen escenas de distintos momentos de su vida, con los demás haciendo familiares, mentores y rivales."},
{id:"regulador-estatus",t:"Regulador de estatus (al tocarse)",c:["Estatus","Relación"],e:"adultos",a:"Edu",src:"guion_2 / Ficha Jamming 28/10",d:"Impro por parejas con espacio y relación dados: uno estatus alto, otro bajo. Cada vez que se tocan, se intercambian los estatus. Cambios justificados y sutiles.",v:"Intercambio al nombrar a la otra persona en vez de al tocarse."},
{id:"pintar-lugar",t:"Pintar el lugar (sin palabras)",c:["Espacio","Mímica","Escucha"],e:"ambos",a:"Edu / Edu Ferrés",src:"MasterClass / guiones",d:"Uno entra al espacio vacío y 'pinta' con mímica un objeto del lugar. Los siguientes recuerdan e interactúan con lo ya creado antes de añadir lo suyo. Sin palabras, hasta construir el lugar completo entre todos.",v:"Playground: un parque donde todos juegan interactuando con lo creado."},
// ==== JUEGOS NUEVOS EXTRAÍDOS DE GUIONES NO PROCESADOS PREVIAMENTE (15/09/2026) ====
{id:"accion-exagerada-simple",t:"Acción exagerada (relevo, versión simple)",c:["Calentamiento","Personaje","Comedia"],e:"niños",a:"Edu",src:"guion_26_cubas / guion_Campamento",d:"Un peque hace una acción sencilla (por ejemplo, atarse los zapatos). El siguiente la repite pero un poco más exagerada. Así sucesivamente hasta que el último hace una versión completamente exagerada y teatral.",v:"Emparentado con 'El personaje agrandado', pero partiendo siempre de una acción física simple en vez de un personaje ya creado; también puede jugarse como 'crear una acción y hacerla más grande en orden', sin partir de una acción dada."},
{id:"caminar-como-personajes",t:"Caminar y comportarse como...",c:["Personaje","Cuerpo","Comedia"],e:"niños",a:"Edu",src:"guion_Campamento (2024-2025)",d:"Todos a la vez adoptan la forma de caminar y de saludarse de un personaje que dicta el coach, jugando con la emoción: ¿cómo camina un abuelito contento? ¿y enfadado? ¿un papá cansado o asustado? ¿un robot desgastado y roto? ¿un león enfadado, un gato triste, una tortuga aburrida, un astronauta con prisas, un pirata amable?",v:"Combinar tipo de personaje y emoción para multiplicar las variantes."},
{id:"si-fueras-personaje-pelicula",t:"Si fueras un personaje de película...",c:["Personaje","Creatividad"],e:"niños",a:"Edu",src:"guion_0503_Serranillos",d:"Pregunta de caldeamiento en círculo: si fueras un personaje de una película, ¿cuál serías y por qué? Cada uno responde y justifica brevemente.",v:"Buena puerta de entrada a un trabajo de personaje o a la impro por estilos de película."},
{id:"uno-dos-tres-palabras",t:"1, 2, 3: que coincidan las palabras",c:["Concentración","Escucha"],e:"niños",a:"Edu",src:"guion_1203_Serranillos / guion_17_cubas",d:"Contando '1, 2, 3' todos a la vez, se intenta que a todos les salga la misma palabra en el mismo golpe, sin haberla acordado antes."},
{id:"cadena-gestos-grupos-mezcla",t:"Cadena de gestos por grupos (con mezcla)",c:["Cuerpo","Concentración","Mímica"],e:"niños",a:"Edu",src:"guion_1111",d:"Grupos de 3-4 personas (A1-A2-A3, B1-B2-B3...). La persona 1 de cada grupo crea un gesto en un recorrido de un punto a otro; al volver se coloca al final de su grupo y el siguiente repite el gesto y añade uno nuevo, ronda tras ronda.",v:"Después se mezclan los grupos (A1 con B2, etc.) representando los gestos combinados de ambos."},
{id:"volcan-de-palabras",t:"Volcán de palabras",c:["Voz","Energía","Escucha"],e:"niños",a:"Edu",src:"guion_17_cubas",d:"Dinámica de calentamiento vocal en la que el grupo hace 'erupcionar' palabras con energía creciente, como un volcán.",v:"Doble volcán: una erupción arriba y otra abajo a la vez."},
{id:"diploma-palabras-bonitas",t:"Diploma de palabras bonitas",c:["Cierre","Relación"],e:"niños",a:"Edu",src:"guion_16_06",d:"Cierre de curso o de clase especial: cada peque escribe en el diploma de un compañero palabras bonitas sobre él o ella."},
{id:"historia-una-frase-peque",t:"Construir una historia: una frase cada peque",c:["Narrativa","Escucha"],e:"niños",a:"Edu",src:"guion_Campamento_dia2",d:"En círculo, se construye una historia colectiva donde cada peque aporta una frase, continuando lo que ha dicho el anterior."},
{id:"acciones-encadenadas-flashback",t:"Acciones encadenadas con memoria (flashback físico)",c:["Cuerpo","Mímica","Concentración"],e:"niños",a:"Edu",src:"guion_27",d:"En círculo, sin palabras articuladas (sí se permiten sonidos). Alguien entra al centro con una acción física clara y anuncia 'Estoy [acción]'. Cada siguiente reacciona con una nueva acción inspirada en la anterior, anunciándola en voz alta.",v:"2ª ronda: igual pero sin verbalizar la acción, que debe inspirarse directamente en la anterior. 3ª ronda: se revive la secuencia en orden inverso, pero cada uno hace la acción que le inspiró la suya (no la propia), creando un efecto de 'flashback' físico y trabajando la memoria corporal."},

// ==== FICHA REENCUENTRO UGENA (juegos propios, 15/09/2026) ====
{id:"presentacion-animal-humor",t:"Presentación con animal (cómo me siento)",c:["Creatividad","Desinhibición"],e:"niños",a:"Edu",src:"Ficha reencuentro Ugena 2026-2027",d:"Ya se conocen de sobra, así que en vez de decir el nombre, cada uno dice cómo se siente hoy, después de las vacaciones, convertido en un animal: \"hoy soy un [animal], porque...\". Sirve de termómetro de grupo y de vuelta suave al ritual del círculo.",v:"Con gesto que el grupo repite después de cada uno."},
{id:"cierre-lo-mejor-de-hoy",t:"Cierre: la ronda de \"lo mejor de hoy\"",c:["Cierre"],e:"niños",a:"Edu",src:"Ficha reencuentro Ugena 2026-2027",d:"En círculo, cada uno dice en una frase corta qué es lo que más le ha gustado de la clase (o del verano). Ritual de despedida antes de que lleguen a buscarlos."},

// ==== CLASE PERSONAJES CON SECRETO (29/09/2026) ====
{id:"guino-ladron",t:"El guiño ladrón",c:["Calentamiento","Observación","Concentración"],e:"niños",a:"Edu",src:"Clase Personajes con secreto (29/09/2026)",d:"Todos caminan por la sala. Con los ojos cerrados, el profe elige en secreto a un ladrón tocándole la espalda. El ladrón 'roba' guiñando un ojo: a quien le guiñan cuenta hasta 3, dice '¡Me han robado!' y se sienta. Los demás pueden acusar, pero si fallan quedan eliminados. Entrena mirar, disimular y sospechar.",v:"Varias rondas cambiando de ladrón; dos ladrones a la vez; un detective fijo en el centro que tiene tres intentos para acertar."},
{id:"caminar-misterioso",t:"Caminar con misterio",c:["Personaje","Cuerpo","Emociones"],e:"niños",a:"Edu",src:"Clase Personajes con secreto (29/09/2026)",d:"Caminar por el espacio con consignas de misterio: alguien que esconde algo en el bolsillo, alguien que cree que le siguen, alguien que sabe un secreto y se muere por contarlo, alguien que llega tarde a una cita misteriosa, alguien que acaba de ver algo que no debía. A la palmada, foto fija; el profe toca un hombro y esa persona dice una frase de su personaje. El misterio se ve en el cuerpo antes de decir nada.",v:"Versión misterio de 'Caminar y comportarse como...'."},
{id:"tres-ingredientes-personaje",t:"Los 3 ingredientes del personaje",c:["Personaje","Cuerpo","Voz"],e:"niños",a:"Edu",src:"Clase Personajes con secreto (29/09/2026)",d:"Cada uno construye un personaje con tres ingredientes: 1) una forma de andar; 2) un gesto que repite (mirar el reloj, jugar con unas llaves, ajustarse la gorra, frotarse las manos...); 3) una frase que siempre dice ('Yo no he visto nada', 'Qué casualidad...', 'Eso no es asunto tuyo'). Se lo presentan en parejas y después cada uno lo enseña al grupo cruzando la sala como en una pasarela.",v:"Encuentro de dos personajes: se cruzan y hablan usando solo su frase y su gesto."},
{id:"objeto-escondido",t:"El objeto escondido",c:["Personaje","Mímica","Observación"],e:"niños",a:"Edu",src:"Clase Personajes con secreto (29/09/2026)",d:"Cada uno imagina que lleva algo escondido (una llave, una carta, una joya, una foto...). Caminan y se cruzan, y tienen que dejar ver que esconden algo sin enseñarlo nunca: tocarse el bolsillo, mirar alrededor, cambiarlo de sitio... Al final el grupo adivina qué llevaba cada uno. El secreto se muestra sin decirlo."},
{id:"sospechoso-silla",t:"El sospechoso en la silla",c:["Personaje","Aceptación","Escucha"],e:"niños",a:"Edu",src:"Clase Personajes con secreto (29/09/2026)",d:"El profe reparte papelitos con un secreto (te has comido la tarta de la fiesta, has roto el jarrón favorito de la dueña, has leído el diario de otra persona, has escondido las llaves del coche, has escuchado detrás de una puerta, has cogido dinero de un cajón pero pensabas devolverlo). Uno se sienta en la silla del sospechoso con su personaje; los demás son detectives y le hacen preguntas (¿dónde estabas?, ¿por qué estás nervioso?...). Tiene que responder a todo sin confesar, usando 'Sí, es verdad... pero...'. Al final el grupo intenta adivinar el secreto. Entrena sostener una mentira en escena.",v:"Sirve para ver quién disfruta mintiendo en escena (buen candidato para el culpable de un Cluedo)."},
{id:"cierre-sobre-misterio",t:"Cierre: el sobre del misterio",c:["Cierre"],e:"niños",a:"Edu",src:"Clase Personajes con secreto (29/09/2026)",d:"En círculo, cada uno dice qué personaje de un compañero le ha gustado más y por qué. El profe termina enseñando un sobre cerrado: 'La semana que viene ocurrirá algo en la mansión... Todos seréis sospechosos. No faltéis.' Deja al grupo con ganas de la siguiente clase."},

// ==== CLASE MISTERIO 2 (06/10/2026) ====
{id:"misiones-secretas-fiesta",t:"Misiones secretas en la fiesta",c:["Personaje","Observación","Escucha"],e:"niños",a:"Edu",src:"Clase misterio 2 (06/10/2026)",d:"Cada peque recibe una tarjeta con una misión secreta, la lee a escondidas y la guarda. Todos están en una fiesta (por ejemplo, en el salón construido antes con 'Pintar el lugar'), cada uno con su personaje: charlan, saludan, brindan y usan los objetos del lugar. Mientras, cada uno debe cumplir su misión sin que nadie se dé cuenta. A los 5-6 minutos, foto fija: el grupo intenta adivinar la misión de cada compañero y después el dueño de la tarjeta la lee en voz alta (la tarjeta decide, así no hay discusiones). Misiones (una por tarjeta): 1) Cambia de sitio cualquier objeto del salón y justifícalo. 2) Escribe en una libreta imaginaria muchas de las cosas que dicen los compañeros. 3) Consigue que dos personas se den la mano. 4) Consigue que alguien diga la palabra 'llave'. 5) Sal del salón y vuelve a entrar 2 veces, con una excusa distinta cada vez. 6) Haz como que se te cae algo y búscalo por el suelo; invita a alguien a que te ayude. 7) Consigue que alguien diga la palabra 'collar'. 8) Cuéntale a alguien un secreto al oído y consigue que lo repita en voz alta. Con 6 peques sobran 2 tarjetas para la segunda ronda. Puntos: misión cumplida sin que nadie la adivine = 2; cumplida pero pillada = 1; adivinar una misión ajena = 1. Trabaja el secreto, el disimulo y la observación.",v:"Segunda ronda con misiones nuevas: ya saben lo que es posible y tienen que disimular mejor. Si alguien cumple su misión demasiado descarado, foto fija y pregunta al grupo: '¿Alguien ha visto algo sospechoso?'."},
];
